function middleSnake(a, leftA, rightA, b, leftB, rightB) {
  const N = rightA - leftA;
  const M = rightB - leftB;
  const MAX = N + M;
  const delta = N - M;
  const isOdd = (delta & 1) === 1;
  const offset = MAX;
  const vf = new Array(2 * MAX + 1).fill(0);
  const vb = new Array(2 * MAX + 1).fill(0);

  vf[offset + 1] = 0;
  vb[offset + 1] = 0;

  for (let d = 0; d <= Math.ceil(MAX / 2); d++) {
    // Forward path
    for (let k = -d; k <= d; k += 2) {
      let x;
      if (k === -d || (k !== d && vf[offset + k - 1] < vf[offset + k + 1])) {
        x = vf[offset + k + 1]; // down (insertion)
      } else {
        x = vf[offset + k - 1] + 1; // right (deletion)
