const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcsLen(a, b) {
  const m = b.length; let prev = new Int32Array(m + 1);
  for (let i = 1; i <= a.length; i++) {
    const cur = new Int32Array(m + 1);
    for (let j = 1; j <= m; j++)
      cur[j] = a[i-1] === b[j-1] ? prev[j-1] + 1 : Math.max(prev[j], cur[j-1]);
    prev = cur;
  }
  return prev[m];
}
function rng(seed) { let s = seed >>> 0; return () => { s = (s*1103515245+12345) & 0x7fffffff; return s; }; }

// heavier randomized validation
for (let seed = 1; seed <= 300; seed++) {
  const rand = rng(seed + 100000);
  const alpha = ['x','y','z','w','', '  c', '-d', '+e'];
  const n = rand() % 60, m = rand() % 60;
  const a = Array.from({length: n}, () => alpha[rand() % alpha.length]);
  // b derived from a with many edits -> stresses divide & conquer
  const b = a.slice();
  const edits = rand() % 20;
  for (let i = 0; i < edits; i++) {
    const r = rand() % 3;
    if (r === 0 && b.length) b.splice(rand() % b.length, 1);
    else if (r === 1) b.splice(rand() % (b.length + 1), 0, alpha[rand() % alpha.length]);
    else if (b.length) b[rand() % b.length] = alpha[rand() % alpha.length];
  }
  const ops = diffLines(a, b);
  assert.deepEqual(ops.filter(o => o.op !== 'insert').map(o => o.line), a);
  assert.deepEqual(ops.filter(o => o.op !== 'delete').map(o => o.line), b);
  const d = ops.filter(o => o.op !== 'equal').length;
  assert.equal(d, a.length + b.length - 2 * lcsLen(a, b), 'minimal');
  for (const context of [0, 1, 3, 7]) {
    const hunks = unifiedHunks(a, b, { context });
    for (const h of hunks) {
      const ob = h.oldLines === 0 ? h.oldStart : h.oldStart - 1;
      const nb = h.newLines === 0 ? h.newStart : h.newStart - 1;
      assert.deepEqual(h.lines.filter(l => l[0] !== '+').map(l => l.slice(1)), a.slice(ob, ob + h.oldLines));
      assert.deepEqual(h.lines.filter(l => l[0] !== '-').map(l => l.slice(1)), b.slice(nb, nb + h.newLines));
    }
    assert.deepEqual(applyHunks(a, hunks), b);
    // corruption: flip one context/delete line -> must throw with index
    if (hunks.length && hunks[0].lines.length) {
      const bad = JSON.parse(JSON.stringify(hunks));
      const i = bad[0].lines.findIndex(l => l[0] === ' ' || l[0] === '-');
      if (i >= 0) {
        bad[0].lines[i] = bad[0].lines[i][0] + 'CORRUPTED_' + bad[0].lines[i].slice(1);
        const grab = fn => { try { fn(); return null; } catch (e) { return e; } };
        assert.match(grab(() => applyHunks(a, bad)).message, /hunk 0 does not apply/);
      }
      // wrong counts -> throw
      const bad2 = JSON.parse(JSON.stringify(hunks));
      bad2[0].oldLines++;
      const grab = fn => { try { fn(); return null; } catch (e) { return e; } };
      assert.match(grab(() => applyHunks(a, bad2)).message, /hunk 0 does not apply/);
    }
  }
}
console.log('heavy random + corruption: ok');

